"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type CompositingPrimitiveProps = ComponentProps<typeof motion.div>;

export function CompositingPrimitive({ children, ...props }: CompositingPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: -80,opacity: 0}}
      animate={{x: 0,opacity: 1}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.52, ease: "linear" }}

    >
      {children}
    </motion.div>
  );
}
